### Python

```python
import sys
import heapq


# 计算操作后的最小数组总和
def solve(n, k, a):
    mx = max(a)

    # 最小素因子筛
    spf = list(range(mx + 1))
    for i in range(2, int(mx ** 0.5) + 1):
        if spf[i] == i:  # i 是质数
            for j in range(i * i, mx + 1, i):
                if spf[j] == j:
                    spf[j] = i

    total = sum(a)
    heap = []

    # 堆中存 (-减少量, 当前值)
    for x in a:
        if x > 1:
            p = spf[x]
            dec = x - x // p
            heapq.heappush(heap, (-dec, x))

    # 贪心执行最多 k 次操作
    for _ in range(k):
        if not heap:
            break

        dec, x = heapq.heappop(heap)
        dec = -dec
        total -= dec  # 减去本次收益

        # 更新当前数
        x //= spf[x]

        # 如果还能继续操作，则加入下一次收益
        if x > 1:
            p = spf[x]
            nxt_dec = x - x // p
            heapq.heappush(heap, (-nxt_dec, x))

    return total


def main():
    data = list(map(int, sys.stdin.read().split()))
    n, k = data[0], data[1]
    a = data[2:2 + n]
    print(solve(n, k, a))


if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.BufferedInputStream;
import java.util.PriorityQueue;

public class Main {

    // 堆中保存当前值和本次操作的减少量
    static class Node {
        int x;
        int dec;

        Node(int x, int dec) {
            this.x = x;
            this.dec = dec;
        }
    }

    // 计算操作后的最小数组总和
    static long solve(int n, int k, int[] a) {
        int mx = 0;
        for (int x : a) {
            mx = Math.max(mx, x);
        }

        // 最小素因子筛
        int[] spf = new int[mx + 1];
        for (int i = 0; i <= mx; i++) {
            spf[i] = i;
        }
        for (int i = 2; i * i <= mx; i++) {
            if (spf[i] == i) { // i 是质数
                for (int j = i * i; j <= mx; j += i) {
                    if (spf[j] == j) {
                        spf[j] = i;
                    }
                }
            }
        }

        long total = 0;
        for (int x : a) {
            total += x;
        }

        // 大根堆：减少量大的优先
        PriorityQueue<Node> pq = new PriorityQueue<>((o1, o2) -> o2.dec - o1.dec);

        // 初始化每个数的第一次操作收益
        for (int x : a) {
            if (x > 1) {
                int p = spf[x];
                int dec = x - x / p;
                pq.offer(new Node(x, dec));
            }
        }

        // 贪心执行最多 k 次操作
        for (int i = 0; i < k; i++) {
            if (pq.isEmpty()) {
                break;
            }

            Node cur = pq.poll();
            total -= cur.dec; // 减去本次收益

            // 当前数更新为除以最小素因子后的值
            int nx = cur.x / spf[cur.x];

            // 若还能继续操作，计算下一次收益再入堆
            if (nx > 1) {
                int p = spf[nx];
                int dec = nx - nx / p;
                pq.offer(new Node(nx, dec));
            }
        }

        return total;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int k = fs.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
        }
        System.out.println(solve(n, k, a));
    }

    // 根据数据范围使用快读
    static class FastScanner {
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;
        private final BufferedInputStream in = new BufferedInputStream(System.in);

        private int read() throws Exception {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        int nextInt() throws Exception {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
}
